INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000001', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000101"]', 'A teammate rebuilds an image after changing one line in the app''s source. What happens to the image''s existing layers?', '[{"text": "Unchanged layers are reused; only layers from the changed step onward are rebuilt as new ones", "correct": true, "why": "Layers are immutable and content-addressed, so a build reuses every layer whose inputs didn''t change.", "misconception": null, "foundation": null}, {"text": "The existing layers are edited in place to include the change", "correct": false, "why": "Layers are never edited: a change produces a new layer with a new digest.", "misconception": "Layers are mutable files on disk", "foundation": null}, {"text": "Every layer is rebuilt, because an image is a single file", "correct": false, "why": "An image is a stack of separate layers plus config, which is why rebuilds can be partial.", "misconception": "An image is one opaque archive", "foundation": null}, {"text": "The config is updated but the layers stay exactly as they were", "correct": false, "why": "The changed step''s layer and those above it must change; the config alone doesn''t hold the code.", "misconception": "Code lives in the image config", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000002', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000101"]', 'Which best describes what an image contains?', '[{"text": "A stack of read-only filesystem layers plus a config saying how to run it", "correct": true, "why": "That''s the image: layers for the filesystem, config for the entrypoint, environment and so on.", "misconception": null, "foundation": null}, {"text": "A running process and its memory", "correct": false, "why": "That''s closer to a container; an image is the inert template it starts from.", "misconception": "Images and containers are the same thing", "foundation": null}, {"text": "Only the application binary, without its dependencies", "correct": false, "why": "Images bundle the dependencies too; that''s what makes them portable.", "misconception": "Images hold only the app", "foundation": null}, {"text": "A list of commands that the host runs on every start", "correct": false, "why": "That''s a build recipe (a Dockerfile); the image is the result of running it once.", "misconception": "An image is its Dockerfile", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000003', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000102"]', 'A container writes a log file to /var/log, then is removed and started again from the same image. Is the log file there?', '[{"text": "No: it lived in that container''s writable layer, which went away with the container", "correct": true, "why": "Each container gets its own thin writable layer on top of the image; removing the container discards it.", "misconception": null, "foundation": null}, {"text": "Yes: writes go into the image, so every new container sees them", "correct": false, "why": "Image layers are read-only; writes never reach them.", "misconception": "Containers write into their image", "foundation": null}, {"text": "Yes, as long as the host wasn''t restarted", "correct": false, "why": "Host restarts aren''t the point: the writable layer belongs to the removed container.", "misconception": "Container files live until reboot", "foundation": null}, {"text": "Only if the image was built with logging enabled", "correct": false, "why": "Build options don''t change where a running container''s writes go.", "misconception": "Persistence is a build setting", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000004', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000102"]', 'Two containers run from the same image on one host. One deletes a file the image provides. What does the other container see?', '[{"text": "The file, unchanged: the delete is recorded only in the first container''s writable layer", "correct": true, "why": "Containers share the read-only image layers; each records its own changes in its own writable layer.", "misconception": null, "foundation": null}, {"text": "The file is gone for both, since they share the image", "correct": false, "why": "They share the read-only layers, which can''t be changed; the delete is per container.", "misconception": "Containers share one filesystem", "foundation": null}, {"text": "An error, because the image is now corrupted", "correct": false, "why": "Nothing in the image changed, so there''s nothing to corrupt.", "misconception": "Containers can damage their image", "foundation": null}, {"text": "The file is gone until the host restarts", "correct": false, "why": "The other container never lost it; restarts don''t come into it.", "misconception": "Changes propagate until reboot", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000005', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000103"]', 'What does a registry store?', '[{"text": "Images, grouped by repository and named by tags", "correct": true, "why": "A registry is image storage: repositories hold an image''s versions, tags name them.", "misconception": null, "foundation": null}, {"text": "Running containers, so they can be moved between hosts", "correct": false, "why": "Registries hold inert images; containers run on hosts.", "misconception": "Registries run containers", "foundation": null}, {"text": "The source code that images are built from", "correct": false, "why": "That''s a source repository (like git); a registry stores the built images.", "misconception": "Registries store source", "foundation": null}, {"text": "Each host''s local cache of images", "correct": false, "why": "Hosts keep their own caches; the registry is the shared, remote store.", "misconception": "The registry is the host cache", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000006', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000103"]', 'In the reference registry.example.com/payments/api:2.4, what is "payments/api"?', '[{"text": "The repository: the name under which every version of this image is kept", "correct": true, "why": "Registry host first, then repository, then the tag after the colon.", "misconception": null, "foundation": null}, {"text": "The tag that picks the version", "correct": false, "why": "The tag is the part after the colon, \"2.4\" here.", "misconception": "Tag and repository are the same", "foundation": null}, {"text": "The digest of the image", "correct": false, "why": "A digest looks like sha256:\u2026 and is never a readable path.", "misconception": "Repository names are digests", "foundation": null}, {"text": "The folder on the host where the image is unpacked", "correct": false, "why": "It''s a name in the registry, not a host path.", "misconception": "References are host paths", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000007', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000104"]', 'Yesterday api:2.4 pointed at one image. Today someone pushed a fix under the same tag. What does api:2.4 refer to now?', '[{"text": "The new image: a tag is a movable name, re-pointed by the push", "correct": true, "why": "Tags are labels that can be moved; pushing under the same tag moves it.", "misconception": null, "foundation": null}, {"text": "Still yesterday''s image, because tags can''t be changed once pushed", "correct": false, "why": "Most registries allow re-pushing a tag unless it''s explicitly made immutable.", "misconception": "Tags are immutable", "foundation": null}, {"text": "Both images, merged into one", "correct": false, "why": "Images aren''t merged; the tag now names only the new one.", "misconception": "Pushing merges images", "foundation": null}, {"text": "Nothing: the push fails because the tag exists", "correct": false, "why": "Re-pushing a tag succeeds by default; that''s exactly why tags drift.", "misconception": "Registries reject repeat tags", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000008', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000104"]', 'A customer wants a reference that will always mean exactly the same image. What should they use?', '[{"text": "The image digest (sha256:\u2026)", "correct": true, "why": "A digest is computed from the image''s content, so it can''t point at anything else.", "misconception": null, "foundation": null}, {"text": "A specific version tag such as 2.4.1", "correct": false, "why": "Even a precise tag can be re-pushed; only the digest is fixed.", "misconception": "Specific tags are fixed", "foundation": null}, {"text": "The latest tag", "correct": false, "why": "latest is the most movable tag of all.", "misconception": "latest means a stable release", "foundation": null}, {"text": "The repository name on its own", "correct": false, "why": "Without a tag or digest a reference defaults to latest, which moves.", "misconception": "Repository alone pins a version", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000009', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000105"]', 'A deployment says image: api:2.4. When does the host decide which image that means?', '[{"text": "When the container starts: the host resolves the reference then", "correct": true, "why": "The reference is resolved at start time, so what a tag means can differ between starts.", "misconception": null, "foundation": null}, {"text": "When the deployment file was written", "correct": false, "why": "The file only holds the reference; nothing is resolved until a container starts.", "misconception": "References resolve when written", "foundation": null}, {"text": "When the image was first built", "correct": false, "why": "Building creates an image; it doesn''t bind future deployments to it.", "misconception": "Builds bind deployments", "foundation": null}, {"text": "Once, when the cluster was created", "correct": false, "why": "Clusters don''t fix references; each start resolves again.", "misconception": "Clusters pin images", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000010', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000001', 'recall', 'understand', '["01SEEDCONCEPT00000000105"]', 'Two replicas of the same deployment started a week apart, both from api:2.4. Can they be running different code?', '[{"text": "Yes: each resolved the tag when it started, and the tag may have moved in between", "correct": true, "why": "Start-time resolution plus movable tags is the usual cause of \"same tag, different behaviour\".", "misconception": null, "foundation": null}, {"text": "No: replicas of one deployment always run identical images", "correct": false, "why": "Only if the reference is a digest, or the tag never moved.", "misconception": "Replicas are always identical", "foundation": null}, {"text": "No: the second replica copies the first one''s image", "correct": false, "why": "Replicas don''t copy from each other; each pulls or uses the host cache.", "misconception": "Replicas clone each other", "foundation": null}, {"text": "Only if the cluster was upgraded in between", "correct": false, "why": "Cluster upgrades aren''t needed; a re-pushed tag is enough.", "misconception": "Only upgrades change images", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000011', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000002', 'recall', 'understand', '["01SEEDCONCEPT00000000201"]', 'What does re-pushing an existing tag do in the registry?', '[{"text": "Points the tag at the newly pushed image", "correct": true, "why": "The tag moves; the old image stays in the registry, untagged unless something else names it.", "misconception": null, "foundation": null}, {"text": "Overwrites the old image''s layers", "correct": false, "why": "Layers are immutable; the push adds new ones and moves the tag.", "misconception": "Pushes overwrite layers", "foundation": null}, {"text": "Creates a second tag with the same name", "correct": false, "why": "A repository has one tag per name; it now points somewhere else.", "misconception": "Tags can be duplicated", "foundation": null}, {"text": "Deletes the old image immediately", "correct": false, "why": "The old image remains until it''s garbage-collected.", "misconception": "Re-pushing deletes the old image", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000012', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000002', 'recall', 'understand', '["01SEEDCONCEPT00000000202"]', 'A host already has an image cached. How does it know whether a tag still means that image?', '[{"text": "By comparing the digest the registry reports for the tag with the cached one", "correct": true, "why": "Hosts cache by digest; only asking the registry tells them where the tag points now.", "misconception": null, "foundation": null}, {"text": "By the tag name alone", "correct": false, "why": "The name can stay the same while the content changes.", "misconception": "Same tag means same image", "foundation": null}, {"text": "By the image''s creation date", "correct": false, "why": "Dates don''t identify content; digests do.", "misconception": "Dates identify images", "foundation": null}, {"text": "It can''t know, so it always re-downloads everything", "correct": false, "why": "With digests it can tell, and it only downloads layers it lacks.", "misconception": "Hosts always re-download", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000013', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000002', 'recall', 'understand', '["01SEEDCONCEPT00000000203"]', 'With pull policy IfNotPresent, what does a host do when it starts a container from api:2.4 and already has an api:2.4 cached?', '[{"text": "Uses the cached image without asking the registry", "correct": true, "why": "IfNotPresent only pulls when the image is missing, so a moved tag goes unnoticed.", "misconception": null, "foundation": null}, {"text": "Always pulls the newest image for that tag", "correct": false, "why": "That''s the Always policy.", "misconception": "IfNotPresent always pulls", "foundation": null}, {"text": "Refuses to start until someone confirms the version", "correct": false, "why": "Pull policies never block for confirmation.", "misconception": "Policies ask for confirmation", "foundation": null}, {"text": "Pulls only if the cached image is older than a day", "correct": false, "why": "Pull policies don''t look at age.", "misconception": "Policies expire cached images", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
INSERT INTO items (id, topic_id, outcome_id, kind, tier, concept_ids_json, stem, options_json, source_ref, model_knowledge, status, created_at) VALUES ('01SEEDITEMBANK000000000014', '01SEEDTOPIC00000000000000T', '01SEEDOUTCOME0000000000002', 'recall', 'understand', '["01SEEDCONCEPT00000000204"]', 'A rolling restart replaces pods of a deployment that uses api:2.4 with pull policy Always. Which image do the new pods run?', '[{"text": "Whatever api:2.4 points at when each new pod starts", "correct": true, "why": "Each new pod resolves the tag at start, so a restart picks up a moved tag.", "misconception": null, "foundation": null}, {"text": "The image the old pods were running", "correct": false, "why": "Restarts don''t carry the old pods'' images over.", "misconception": "Restarts keep the old image", "foundation": null}, {"text": "The image from when the deployment was created", "correct": false, "why": "Creation time doesn''t pin anything.", "misconception": "Deployments pin at creation", "foundation": null}, {"text": "The latest tag, regardless of the reference", "correct": false, "why": "The reference says 2.4; latest isn''t involved.", "misconception": "Restarts switch to latest", "foundation": null}]', NULL, 1, 'active', '2026-10-25 09:20:00');
